import {useEffect,useMemo,useRef,useState} from 'react';
import {api,patch,post} from '../api/client';
import {DataTable} from '../components/DataTable';
import {FormField} from '../components/FormField';
import {Modal} from '../components/Modal';
import {OwnerModal} from '../components/OwnerModal';
import {PageHeader} from '../components/PageHeader';
import {PaymentModal} from '../components/PaymentModal';
import {RecordModal} from '../components/RecordModal';
import {StatusPill} from '../components/StatusPill';
import {useApi} from '../hooks/useApi';
import {installmentStatus,money,shortDate} from '../utils/format';
import {filterByPeriod,formatPeriod} from '../utils/periods.mjs';

const descriptions={contracts:'Vigencia, ajustes, garantías y honorarios en un solo lugar.',properties:'Cada inmueble vinculado con sus titulares y contratos.',owners:'Titulares de inmuebles y datos fiscales.',tenants:'Inquilinos ubicados por contrato.',guarantors:'Garantes y respaldos vinculados a contratos.',collections:'Cobros ya registrados.', 'pending-collections':'Alquileres futuros o vencidos todavía no cobrados.',expenses:'Gastos generales de la inmobiliaria.',services:'Servicios asociados a inmuebles o contratos.', 'other-income':'Ingresos no asociados a alquiler mensual.',incidents:'Reclamos y temas operativos con seguimiento.',documents:'Archivos originales y relaciones creadas automáticamente.',imports:'Lecturas automáticas y observaciones documentales.'};
const titles={contracts:'Contratos',properties:'Propiedades',owners:'Propietarios',tenants:'Inquilinos',guarantors:'Garantes',people:'Personas',collections:'Cobros', 'pending-collections':'Cobros pendientes',expenses:'Gastos',services:'Servicios', 'other-income':'Otros ingresos',incidents:'Incidencias',documents:'Documentos',imports:'Importaciones'};

function UploadZone({onUpload,notify}){const[dragging,setDragging]=useState(false),[uploading,setUploading]=useState(false);const handleDrop=async e=>{e.preventDefault();e.stopPropagation();setDragging(false);const files=Array.from(e.dataTransfer.files).filter(f=>/\.pdf$/i.test(f.name));if(!files.length)return notify('Solo se aceptan archivos PDF.');setUploading(true);for(const file of files){const formData=new FormData();formData.append('file',file);try{const res=await fetch('/api/imports/upload',{method:'POST',body:formData});const data=await res.json();if(!res.ok)throw new Error(data.error||`Error ${res.status}`);notify(data.status==='Revisión'?`⚠ ${data.filename}: faltan datos obligatorios para completar.`:`✓ ${data.filename}: ${data.status}`);}catch(error){notify(`✗ ${file.name}: ${error.message}`)}}setUploading(false);onUpload({silent:true})};return <div className="upload-zone" onDragOver={e=>{e.preventDefault();setDragging(true)}} onDragLeave={()=>setDragging(false)} onDrop={handleDrop} style={{borderColor:dragging?'#26705a':'#d1d5db',backgroundColor:dragging?'#e3f2e9':'transparent',opacity:uploading?0.5:1,pointerEvents:uploading?'none':'auto'}}><div style={{textAlign:'center',padding:'2rem',pointerEvents:'none'}}><div style={{fontSize:'2rem',marginBottom:'0.5rem'}}>📄</div><h3>Arrastra archivos aquí</h3><p>PDF de contratos</p>{uploading&&<p style={{marginTop:'1rem'}}>Subiendo...</p>}</div></div>}

const reviewDefaults=row=>{const parsed=row?.result_json?.parsed||{},owner=parsed.owners?.[0]||{},tenant=(parsed.tenants?.[0]||parsed.tenant)||{},guarantee=parsed.guarantee||{},resolution=row?.result_json?.entity_resolution||{},propertyCandidate=resolution.property?.candidates?.[0];return{property_id:propertyCandidate?.match==='EXACT_MATCH'?propertyCandidate.id:'',alias:parsed.alias||'',address:parsed.address||'',property_type:parsed.propertyType||'Departamento',rental_type:parsed.rentalType||'Residencial',owner_full_name:owner.fullName||'',owner_document_number:owner.documentNumber||'',tenant_full_name:tenant.fullName||'',tenant_document_number:tenant.documentNumber||'',start_date:parsed.startDate||'',end_date:parsed.endDate||'',duration_months:parsed.durationMonths||'',initial_amount:parsed.initialAmount||'',deposit_amount:parsed.depositAmount||'',currency:parsed.currency||'ARS',adjustment_type:parsed.adjustmentType||parsed.adjustmentIndex||'IPC',adjustment_value_pct:parsed.adjustmentValuePct||'',ipc_lag_months:parsed.ipcLagMonths||0,adjustment_frequency_months:parsed.adjustmentFrequencyMonths||'',adjustment_index:parsed.adjustmentIndex||'IPC',payment_period_start_day:parsed.paymentPeriodStartDay||'',payment_period_end_day:parsed.paymentPeriodEndDay||parsed.paymentDueDay||10,payment_due_day:parsed.paymentDueDay||parsed.paymentPeriodEndDay||10,bank_name:parsed.bankName||'',cbu:parsed.cbu||'',late_fee_type:parsed.lateFee?.type||'NONE',late_fee_daily_pct:parsed.lateFee?.dailyPercentage||'',prepaid_rent_months:parsed.paymentTerms?.prepaidRentMonths||'',vat_applicable:parsed.vat?.applicable||false,vat_percentage:parsed.vat?.percentage||'',guarantee_type:guarantee.type||'Otra',guarantee_provider:guarantee.provider||'Otra',guarantee_provider_detail:guarantee.providerDetail||''};};

function ReviewSection({title,children}){return <section className="review-section"><h3>{title}</h3><div className="form-grid">{children}</div></section>}
function CandidateList({title,resolution}){const candidates=resolution?.candidates||[];return <div className="candidate-box full"><strong>{title}</strong>{!candidates.length?<span>No hay coincidencias claras en la base. Si confirmás, se crea con los datos detectados.</span>:<ul>{candidates.map(candidate=><li key={candidate.id}><b>{candidate.address||candidate.full_name}</b><span>{candidate.match} · confianza {Math.round((candidate.score||1)*100)}%</span></li>)}</ul>}</div>}

function ImportReviewModal({row,onClose,onSaved,notify}){const[saving,setSaving]=useState(false),[form,setForm]=useState(reviewDefaults(row));useEffect(()=>{setForm(reviewDefaults(row));},[row]);if(!row)return null;const draft=row.result_json||{},parsed=draft.parsed||{},missing=draft.blocking_fields||draft.missing_fields||[],warnings=draft.warnings||row.warnings||[],resolution=draft.entity_resolution||{},preview=draft.preview||[];const propertyOptions=[['','Crear nueva / no asociar'],...(resolution.property?.candidates||[]).map(candidate=>[candidate.id,candidate.address])];const change=event=>{const{name,value,type,checked}=event.target;setForm(current=>({...current,[name]:type==='checkbox'?checked:value}));};async function submit(event){event.preventDefault();setSaving(true);try{await post(`imports/${row.id}/complete`,form);await onSaved({silent:true});notify('Contrato confirmado y creado.');onClose();}catch(error){notify(error.message);}finally{setSaving(false);}}return <Modal open title="Revisar importación de contrato" subtitle="CONTRACT_IMPORT / DRAFT" onClose={onClose} footer={<><button className="button secondary" type="button" onClick={onClose}>Cancelar</button><button className="button primary" form="import-review-form" disabled={saving}>{saving?'Confirmando…':'Confirmar y crear contrato'}</button></>}><div className={`notice compact ${missing.length?'':'success'}`}><b>{missing.length?'!':'✓'}</b><div><strong>{missing.length?'Faltan datos bloqueantes':'Listo para confirmar'}</strong><span>{missing.length?missing.map(item=>item.label).join(', '):'El PDF fue analizado. Revisá las entidades y confirmá cuando esté correcto.'}</span></div></div>{warnings.length?<ul className="warnings review-warnings">{warnings.map(item=><li key={item}>{item}</li>)}</ul>:null}<form id="import-review-form" className="review-form" onSubmit={submit}><ReviewSection title="1. Propiedad"><CandidateList title="Coincidencias de propiedad" resolution={resolution.property}/>{resolution.property?.candidates?.length?<FormField label="Asociar propiedad existente" name="property_id" as="select" value={form.property_id} onChange={change} options={propertyOptions}/>:null}<FormField label="Dirección detectada / a crear" name="address" value={form.address} onChange={change} full required/><FormField label="Tipo de inmueble" name="property_type" as="select" value={form.property_type} onChange={change} options={['Departamento','Casa','Local','Oficina','PH','Otro']}/><FormField label="Tipo de alquiler" name="rental_type" as="select" value={form.rental_type} onChange={change} options={['Residencial','Comercial','Profesional','Temporario','Otro']}/></ReviewSection><ReviewSection title="2. Propietarios"><CandidateList title="Coincidencias de propietario" resolution={resolution.owners?.[0]}/><FormField label="Propietario principal" name="owner_full_name" value={form.owner_full_name} onChange={change} required/><FormField label="DNI/CUIT propietario" name="owner_document_number" value={form.owner_document_number} onChange={change} required/><div className="candidate-box full"><strong>Composición</strong><span>Si hay varios propietarios detectados, se conservarán al confirmar. La composición se crea completa al 100% repartida entre titulares detectados.</span>{parsed.owners?.length>1?<ul>{parsed.owners.map(owner=><li key={owner.documentNumber}><b>{owner.fullName}</b><span>{owner.documentNumber}</span></li>)}</ul>:null}</div></ReviewSection><ReviewSection title="3. Inquilinos"><CandidateList title="Coincidencias de inquilino" resolution={resolution.tenants?.[0]}/><FormField label="Inquilino principal" name="tenant_full_name" value={form.tenant_full_name} onChange={change} required/><FormField label="DNI/CUIT inquilino" name="tenant_document_number" value={form.tenant_document_number} onChange={change} required/></ReviewSection><ReviewSection title="4. Vigencia"><FormField label="Alias interno" name="alias" value={form.alias} onChange={change} full/><FormField label="Inicio" name="start_date" type="date" value={form.start_date} onChange={change} required/><FormField label="Finalización" name="end_date" type="date" value={form.end_date} onChange={change}/><FormField label="Duración (meses)" name="duration_months" type="number" min="1" value={form.duration_months} onChange={change} required/></ReviewSection><ReviewSection title="5. Condiciones económicas"><FormField label="Canon inicial" name="initial_amount" type="number" min="0" step="0.01" value={form.initial_amount} onChange={change} required/><FormField label="Depósito" name="deposit_amount" type="number" min="0" step="0.01" value={form.deposit_amount} onChange={change}/><FormField label="Moneda" name="currency" as="select" value={form.currency} onChange={change} options={['ARS','USD','EUR','OTHER']}/><FormField label="Banco" name="bank_name" value={form.bank_name} onChange={change}/><FormField label="CBU" name="cbu" value={form.cbu} onChange={change}/><FormField label="IVA %" name="vat_percentage" type="number" min="0" step="0.01" value={form.vat_percentage} onChange={change}/></ReviewSection><ReviewSection title="6. Ajustes y vencimiento"><FormField label="Tipo de ajuste" name="adjustment_type" as="select" value={form.adjustment_type} onChange={change} options={['IPC','ICL','FIXED_PERCENTAGE','MANUAL','CUSTOM_INDEX']}/><FormField label="Índice" name="adjustment_index" as="select" value={form.adjustment_index} onChange={change} options={['IPC','ICL','CAC','Acuerdo de partes']}/><FormField label="Ajuste cada (meses)" name="adjustment_frequency_months" type="number" min="1" value={form.adjustment_frequency_months} onChange={change}/><FormField label="% fijo si corresponde" name="adjustment_value_pct" type="number" min="0" step="0.01" value={form.adjustment_value_pct} onChange={change}/><FormField label="Rezago IPC (meses)" name="ipc_lag_months" type="number" min="0" max="2" value={form.ipc_lag_months} onChange={change}/><FormField label="Vence desde día" name="payment_period_start_day" type="number" min="1" max="31" value={form.payment_period_start_day} onChange={change}/><FormField label="Vence hasta/día" name="payment_period_end_day" type="number" min="1" max="31" value={form.payment_period_end_day} onChange={change}/><FormField label="Due day operativo" name="payment_due_day" type="number" min="1" max="31" value={form.payment_due_day} onChange={change}/></ReviewSection><ReviewSection title="7. Punitorios, garantía y pagos iniciales"><FormField label="Tipo de punitorio" name="late_fee_type" as="select" value={form.late_fee_type} onChange={change} options={['NONE','FIXED_DAILY','BANK_ACTIVE_RATE']}/><FormField label="% diario punitorio" name="late_fee_daily_pct" type="number" min="0" step="0.01" value={form.late_fee_daily_pct} onChange={change}/><FormField label="Alquiler anticipado (meses)" name="prepaid_rent_months" type="number" min="0" value={form.prepaid_rent_months} onChange={change}/><FormField label="Tipo de respaldo" name="guarantee_type" as="select" value={form.guarantee_type} onChange={change} options={['Seguro de caución','Garantía propietaria','Sin garantía','Otra']}/><FormField label="Empresa / proveedor" name="guarantee_provider" as="select" value={form.guarantee_provider} onChange={change} options={['Respaldar','Argenprop','Otra']}/><FormField label="Detalle garantía" name="guarantee_provider_detail" value={form.guarantee_provider_detail} onChange={change} full/></ReviewSection>{preview.length?<ReviewSection title="8. Vista previa de alquileres">{preview.map(item=><div className="rent-preview" key={item.period}><strong>{item.period}</strong><span>{item.note||money(item.amount,item.currency)}</span></div>)}</ReviewSection>:null}</form></Modal>}

function ImportsPanel({rows,reload,notify,columns}){const processed=rows.filter(row=>row.status==='Procesado').length,review=rows.filter(row=>row.status==='Revisión').length,errors=rows.filter(row=>row.status==='Error').length,lastImport=rows[0]?.created_at,previousCount=useRef(rows.length);useEffect(()=>{const timer=setInterval(()=>{reload({silent:true});},6000);return()=>clearInterval(timer);},[reload]);useEffect(()=>{if(rows.length>previousCount.current){const delta=rows.length-previousCount.current;notify(`Se detectó${delta===1?'':'n'} ${delta} contrato${delta===1?'':'s'} nuevo${delta===1?'':'s'} en la carpeta.`);}previousCount.current=rows.length;},[rows,notify]);return <div className="imports-page"><section className="imports-hero card"><div><p className="eyebrow">CENTRO DOCUMENTAL</p><h2>Importaciones de contratos</h2><p>Acá vas a concentrar la entrada de PDFs, los resultados del parser y los casos que requieren revisión manual.</p><div className="imports-stats"><article><strong>{rows.length}</strong><span>Lecturas registradas</span></article><article><strong>{processed}</strong><span>Procesadas</span></article><article><strong>{review}</strong><span>En revisión</span></article><article><strong>{errors}</strong><span>Con error</span></article></div></div><aside className="imports-side"><UploadZone onUpload={reload} notify={notify}/><div className="imports-note"><strong>Última actividad</strong><span>{lastImport?shortDate(lastImport):'Todavía no hay lecturas registradas.'}</span></div></aside></section><DataTable columns={columns} rows={rows} className="imports-table" empty="Todavía no hay importaciones" /></div>;}

function PropertyMetric({tone,label,value,icon}){return <article className={`property-metric ${tone||''}`.trim()}><span>{icon}</span><div><small>{label}</small><strong>{value}</strong></div></article>}
function propertyStatus(row){return row.status==='Alquilada'||Number(row.active_contracts)>0?'Ocupado':'Libre'}
function PropertiesPanel({rows,onCreate}){const[search,setSearch]=useState(''),[sort,setSort]=useState('address');const summary=useMemo(()=>{const total=rows.length,occupied=rows.filter(row=>propertyStatus(row)==='Ocupado').length,free=total-occupied;return{total,occupied,free,rate:total?Math.round((occupied/total)*100):0};},[rows]);const shown=useMemo(()=>rows.filter(row=>JSON.stringify(row).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>String(a[sort]||'').localeCompare(String(b[sort]||''),'es')),[rows,search,sort]);return <div className="properties-page"><header className="properties-heading"><div><h2>Propiedades</h2></div></header><div className="properties-commandbar"><button className="button primary big-action" onClick={onCreate}>+ Nueva propiedad</button></div><section className="occupancy-card card"><h3>Resumen de ocupación</h3><div className="property-metrics"><PropertyMetric icon="⌂" label="Total Propiedades" value={summary.total}/><PropertyMetric icon="♙" tone="success" label="Ocupadas" value={summary.occupied}/><PropertyMetric icon="⌂" label="Libres" value={summary.free}/><PropertyMetric icon="↗" tone="warning" label="Tasa de ocupación" value={`${summary.rate}%`}/></div></section><section className="properties-table-card card"><div className="property-toolbar"><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Buscar propiedad..." aria-label="Buscar propiedad"/><select value={sort} onChange={event=>setSort(event.target.value)} aria-label="Ordenar propiedades"><option value="address">Dirección</option><option value="city">Ciudad</option><option value="province">Provincia</option><option value="status">Estado</option></select></div><p className="properties-count">Mostrando {shown.length} de {rows.length} propiedades</p><label className="select-all-row"><input type="checkbox"/> <span>Seleccionar todas en esta lista</span></label><div className="properties-table-scroll"><table className="properties-table"><thead><tr><th></th><th>Dirección ^</th><th>Ciudad/Barrio ^</th><th>Provincia ^</th><th>Contrato ^</th><th>Estado ^</th></tr></thead><tbody>{shown.map(row=>{const status=propertyStatus(row);return <tr key={row.id}><td><input type="checkbox"/></td><td><strong>{row.address}</strong>{row.owners&&<small>{row.owners}</small>}</td><td>{row.city||row.neighborhood||'—'}</td><td>{row.province||'—'}</td><td>{row.active_contract_code||row.active_contract_alias?<><a href="#contracts">{row.active_contract_alias||row.active_contract_code}</a>{row.active_tenant&&<small>{row.active_tenant}</small>}</>:<span className="muted">—</span>}</td><td><span className={`property-status ${status==='Ocupado'?'occupied':'free'}`}>{status}</span>{row.active_tenant&&<small>{row.active_tenant}</small>}</td></tr>})}</tbody></table></div>{!shown.length&&<div className="empty"><strong>No encontramos propiedades</strong><span>Probá con otra búsqueda o creá una nueva propiedad.</span></div>}</section></div>}

const OWNER_PROPERTIES_PREVIEW=3;
function OwnerProperties({owner,expanded}){const list=Array.isArray(owner.properties_list)?owner.properties_list:[];if(!list.length)return <span className="muted">Sin propiedades</span>;const visible=expanded?list:list.slice(0,OWNER_PROPERTIES_PREVIEW),hidden=list.length-visible.length;return <div className="owner-properties">{visible.map(property=><span key={property.id} className="owner-property-chip" title={property.code?`${property.address} · ${property.code}`:property.address}>{property.address}</span>)}{hidden>0&&<span className="owner-property-more">+{hidden} más</span>}</div>}
function OwnersPanel({rows,onCreate,onEdit}){const[expanded,setExpanded]=useState(null);return <div className="owners-page"><header className="owners-heading"><h2>Propietarios</h2><p>Personas y empresas titulares asociadas a la cartera de inmuebles.</p></header><button className="button primary big-action" onClick={onCreate}>+ Nuevo propietario</button><section className="owners-table-card card"><div className="owners-table-scroll"><table className="owners-table"><thead><tr><th>Nombre</th><th>Email</th><th>Propiedades</th><th>Acciones</th></tr></thead><tbody>{rows.map(owner=><tr key={owner.id}><td><div className="owner-cell"><strong>{owner.full_name}</strong><small>{owner.person_kind==='COMPANY'?'Empresa':'Persona'}{owner.document_number?` · ${owner.document_type||'DNI'} ${owner.document_number}`:''}{owner.tax_id?` · CUIT ${owner.tax_id}`:''}</small>{expanded===owner.id&&<div className="owner-details"><span>Teléfono: {owner.phone||'—'}</span><span>WhatsApp: {owner.whatsapp||'—'}</span><span>IVA: {owner.vat_condition||'—'}</span><span>Aviso por correo: {owner.liquidation_email_enabled?'Activo':'Inactivo'}</span><span>Propiedades: {owner.properties_count||0}</span></div>}</div></td><td>{owner.email||'—'}</td><td><OwnerProperties owner={owner} expanded={expanded===owner.id}/></td><td><div className="owner-actions"><button className="button small secondary" type="button" onClick={()=>setExpanded(expanded===owner.id?null:owner.id)}>{expanded===owner.id?'Ocultar':'Ver datos'}</button><button className="button small primary" type="button" onClick={()=>onEdit(owner)}>Editar</button></div></td></tr>)}</tbody></table></div>{!rows.length&&<div className="empty"><strong>No hay propietarios cargados</strong><span>Creá propietarios o asociá personas existentes a propiedades.</span></div>}</section></div>}

function splitTenantName(row){const parts=String(row?.full_name||'').trim().split(/\s+/);return{first_name:row?.first_name||parts.slice(0,1).join(' '),last_name:row?.last_name||parts.slice(1).join(' ')}}
function tenantDefaults(row){const names=splitTenantName(row);return{first_name:names.first_name||'',last_name:names.last_name||'',document_number:row?.document_number||'',tax_id:row?.tax_id||'',nationality:row?.nationality||'Argentina',address:row?.address||'',city:row?.city||'',province:row?.province||'',country:row?.country||'Argentina',phone:row?.phone||'',whatsapp:row?.whatsapp||'',email:row?.email||'',person_kind:row?.person_kind||'PERSON',vat_condition:row?.vat_condition||'Consumidor final'};}
function TenantEditModal({tenant,onClose,onSaved,notify}){const[form,setForm]=useState(tenantDefaults(tenant)),[saving,setSaving]=useState(false);useEffect(()=>setForm(tenantDefaults(tenant)),[tenant]);if(!tenant)return null;const change=event=>{const{name,value}=event.target;setForm(current=>({...current,[name]:value}));};async function submit(event){event.preventDefault();setSaving(true);try{await patch(`tenants/${tenant.id}`,{...form,full_name:[form.first_name,form.last_name].filter(Boolean).join(' ').trim(),document_type:'DNI'});notify('Inquilino actualizado correctamente.');await onSaved();onClose();}catch(error){notify(error.message);}finally{setSaving(false);}}return <Modal open title="Editar inquilino" subtitle={`Modificá la información del inquilino ${tenant.full_name}.`} onClose={onClose} footer={<><button className="button secondary" type="button" onClick={onClose}>Cancelar</button><button className="button primary" form="tenant-edit-form" disabled={saving}>{saving?'Guardando…':'Guardar cambios'}</button></>}><form id="tenant-edit-form" className="tenant-form" onSubmit={submit}><FormField label="Nombre*" name="first_name" value={form.first_name} onChange={change} required/><FormField label="Apellido*" name="last_name" value={form.last_name} onChange={change} required/><FormField label="DNI*" name="document_number" value={form.document_number} onChange={change} full required/><FormField label="CUIT*" name="tax_id" value={form.tax_id} onChange={change} full required/><FormField label="Nacionalidad" name="nationality" as="select" value={form.nationality} onChange={change} options={['Argentina','Uruguay','Paraguay','Bolivia','Chile','Brasil','Otra']} full/><FormField label="Dirección" name="address" value={form.address} onChange={change} full/><FormField label="Ciudad" name="city" value={form.city} onChange={change}/><FormField label="Provincia/Estado" name="province" value={form.province} onChange={change}/><FormField label="País" name="country" as="select" value={form.country} onChange={change} options={['Argentina','Uruguay','Paraguay','Bolivia','Chile','Brasil','Otro']} full/><FormField label="Teléfono" name="phone" value={form.phone} onChange={change}/><FormField label="WhatsApp" name="whatsapp" value={form.whatsapp} onChange={change}/><FormField label="Email" name="email" type="email" value={form.email} onChange={change} placeholder="Ingrese el email (para recordatorios)" full/><FormField label="Tipo" name="person_kind" as="select" value={form.person_kind} onChange={change} options={[['PERSON','Persona física'],['COMPANY','Empresa']]}/><FormField label="Condición frente al IVA" name="vat_condition" as="select" value={form.vat_condition} onChange={change} options={['Consumidor final','Monotributista','Responsable inscripto','Exento']} help="Se usa para determinar el tipo de factura que corresponde emitir."/></form></Modal>}
function TenantGuarantorsModal({tenant,onClose}){const guarantors=tenant?.guarantors_json||[];if(!tenant)return null;return <Modal open title="Garantes" subtitle="" onClose={onClose}><div className="tenant-guarantors"><table><thead><tr><th>Nombre</th><th>Documento</th><th>Email</th><th>Teléfono</th><th>Domicilio</th></tr></thead><tbody>{guarantors.map(guarantor=><tr key={guarantor.id}><td>{guarantor.full_name||'—'}</td><td>{guarantor.document_number||'—'}</td><td>{guarantor.email||'—'}</td><td>{guarantor.phone||'—'}</td><td>{guarantor.address||guarantor.provider_detail||guarantor.provider||'—'}</td></tr>)}</tbody></table>{!guarantors.length&&<div className="empty"><strong>Este inquilino no tiene garantes cargados</strong><span>Los garantes se vinculan desde el contrato correspondiente.</span></div>}</div></Modal>}
