const toAmount=value=>{const raw=String(value??'').trim();if(!raw)return 0;return Number(raw.includes(',')?raw.replace(/\./g,'').replace(',','.'):raw)||0;};
function MoneyInput({value,onChange,disabled=false}){return <label className="money-control"><span>$</span><input type="number" min="0" step="0.01" value={value} disabled={disabled} onChange={event=>onChange(event.target.value)}/></label>}
function ToggleRow({label,checked,onChange,children}){return <label className="switch-row pending-switch"><span>{label}{children}</span><input type="checkbox" checked={checked} onChange={event=>onChange(event.target.checked)}/><i/></label>}
