export function ResourcePage({resource,notify}){const{data,error,loading,reload}=useApi(resource);const[creating,setCreating]=useState(false),[payment,setPayment]=useState(null),[reviewing,setReviewing]=useState(null),[editingOwner,setEditingOwner]=useState(null);if(loading)return <div className="loading">Cargando {titles[resource].toLowerCase()}…</div>;if(error)throw error;const columns=makeColumns(resource,{reload,notify,setPayment,setReviewing});const canCreate=['contracts','properties','owners','incidents','expenses','services','other-income'].includes(resource);const importsView=resource==='imports',propertiesView=resource==='properties',ownersView=resource==='owners',peopleRoleView=['tenants','guarantors'].includes(resource),pendingView=resource==='pending-collections',pastCollectionsView=resource==='collections',financeLedgerView=['expenses','services','other-income'].includes(resource),ownerModalOpen=ownersView&&(creating||Boolean(editingOwner));return <>{!importsView&&!propertiesView&&!ownersView&&!peopleRoleView&&!pendingView&&!pastCollectionsView&&!financeLedgerView&&<PageHeader title={titles[resource]} description={descriptions[resource]}>{canCreate&&<button className="button primary" onClick={()=>setCreating(true)}>+ Agregar</button>}</PageHeader>}{importsView?<ImportsPanel rows={data} reload={reload} notify={notify} columns={columns}/>:propertiesView?<PropertiesPanel rows={data} onCreate={()=>setCreating(true)} notify={notify}/>:ownersView?<OwnersPanel rows={data} onCreate={()=>setCreating(true)} onEdit={setEditingOwner} notify={notify}/>:peopleRoleView?<PeopleRolePanel resource={resource} rows={data} reload={reload} notify={notify}/>:pendingView?<PendingCollectionsPanel rows={data} reload={reload} notify={notify} onCreate={()=>setPayment({})} onPay={setPayment}/>:pastCollectionsView?<CollectionsPastPanel rows={data} onCreate={()=>setPayment({})}/>:financeLedgerView?<FinanceLedgerPanel resource={resource} rows={data} onCreate={()=>setCreating(true)}/>:<DataTable columns={columns} rows={data}/>} {ownersView?<OwnerModal open={ownerModalOpen} owner={editingOwner} onClose={()=>{setCreating(false);setEditingOwner(null);}} onSaved={reload} notify={notify}/>:<RecordModal resource={resource} open={creating} onClose={()=>setCreating(false)} onSaved={reload} notify={notify}/>}<PaymentModal installment={payment} onClose={()=>setPayment(null)} onSaved={reload} notify={notify}/><ImportReviewModal row={reviewing} onClose={()=>setReviewing(null)} onSaved={reload} notify={notify}/></>}

function primary(title,subtitle){return <><strong>{title||'—'}</strong>{subtitle&&<small>{subtitle}</small>}</>}
async function discardImport(row,actions){
  if(!confirm(`¿Descartar la importación "${row.filename}"?\n\nNo se creará ningún contrato ni se usará esta lectura.`))return;
  try{await post(`imports/${row.id}/discard`,{reason:'Descartada desde importaciones'});actions.notify('Importación descartada.');actions.reload({silent:true});}
  catch(error){actions.notify(error.message);}
}
async function revertImport(row,actions){
  if(!confirm(`¿Revertir la importación "${row.filename}"?\n\nSe eliminará el contrato creado, su documento y sus cobros pendientes si no existen pagos registrados. No se borrarán datos compartidos o sin trazabilidad segura.`))return;
  try{await post(`imports/${row.id}/revert`,{reason:'Revertida desde importaciones'});actions.notify('Importación revertida correctamente.');actions.reload({silent:true});}
  catch(error){actions.notify(error.message);}
}
async function voidContract(row,actions){
  const reason=prompt(`Motivo para anular el contrato ${row.code}:`,'Cargado por error');
  if(reason===null)return;
  if(!confirm(`¿Anular el contrato ${row.code}?\n\nNo se borra información histórica. El contrato dejará de generar cobros pendientes.`))return;
  try{await post(`contracts/${row.id}/void`,{reason});actions.notify('Contrato anulado.');actions.reload({silent:true});}
  catch(error){actions.notify(error.message);}
}
function RenewalCandidateCard({candidate,selected,onSelect}){return <label className={`renewal-candidate ${selected?'selected':''}`}><input type="radio" name="new_contract_id" value={candidate.id} checked={selected} onChange={()=>onSelect(candidate.id)}/><div><div className="renewal-candidate-head"><strong>{candidate.alias||candidate.code}</strong><StatusPill>{candidate.status}</StatusPill></div><dl><dt>Propiedad</dt><dd>{candidate.property}</dd><dt>Inquilino</dt><dd>{candidate.tenant}</dd><dt>Vigencia</dt><dd>{shortDate(candidate.start_date)} → {shortDate(candidate.end_date)}</dd><dt>Canon</dt><dd>{money(candidate.initial_amount,candidate.currency)} ({candidate.currency})</dd><dt>Documento</dt><dd>{candidate.document_filename||'—'}</dd></dl>{candidate.tenant_changed&&<small className="renewal-warning">El inquilino es distinto al del contrato actual. Verificá que sea correcto.</small>}{candidate.overlaps_previous&&<small className="renewal-warning">Comienza antes de que termine el contrato actual: las cuotas futuras sin pagos del contrato actual quedarán sustituidas.</small>}</div></label>}
function ContractRenewModal({contract,onClose,actions}){const[state,setState]=useState({loading:true,data:null,error:null}),[selected,setSelected]=useState(''),[saving,setSaving]=useState(false);useEffect(()=>{if(!contract)return;let active=true;setSelected('');setState({loading:true,data:null,error:null});api(`contracts/${contract.id}/renewal-candidates`).then(data=>{if(active){setState({loading:false,data,error:null});if(data.candidates?.length===1)setSelected(data.candidates[0].id);}}).catch(error=>{if(active)setState({loading:false,data:null,error:error.message});});return()=>{active=false;};},[contract]);if(!contract)return null;const data=state.data,candidates=data?.candidates||[],choice=candidates.find(item=>item.id===selected);function goToImports(){onClose();location.hash='imports';}async function submit(e){e.preventDefault();if(!choice)return;if(!confirm(`¿Vincular ${choice.alias||choice.code} como renovación de ${contract.alias||contract.code}?\n\nEl contrato actual pasará a “Renovado” y conservará su PDF, cuotas y pagos. El nuevo contrato quedará activo con los datos de su propio PDF.`))return;setSaving(true);try{const result=await post(`contracts/${contract.id}/renew`,{new_contract_id:choice.id});const substituted=result.substituted_installments?.length||0,kept=result.kept_overlapping_installments?.length||0;actions.notify(`Contrato renovado.${substituted?` ${substituted} cuota${substituted===1?'':'s'} futura${substituted===1?'':'s'} del contrato anterior quedaron sustituidas.`:''}${kept?` ${kept} cuota${kept===1?'':'s'} con pagos se conservaron en el contrato anterior.`:''}`);actions.reload({silent:true});onClose();}catch(error){actions.notify(error.message);}finally{setSaving(false);}}return <Modal open title="Renovar contrato" subtitle={contract.alias||contract.code} onClose={onClose} footer={<><button className="button secondary" type="button" onClick={onClose}>Cancelar</button>{candidates.length>0&&<button className="button primary" form="contract-renew-form" disabled={saving||!choice}>{saving?'Vinculando…':'Confirmar renovación'}</button>}</>}><div className="renewal-current"><span>Contrato actual</span><b>{contract.property}</b><small>{contract.tenant} · {shortDate(contract.start_date)} → {shortDate(contract.end_date)} · {money(contract.initial_amount,contract.currency)}</small></div><p className="renewal-intro">Para renovar este contrato es necesario seleccionar un nuevo contrato previamente cargado desde su PDF firmado. No se copian datos del contrato actual.</p>{state.loading?<div className="loading">Buscando contratos importados…</div>:state.error?<div className="notice compact"><b>!</b><div><strong>No se pudieron cargar los contratos</strong><span>{state.error}</span></div></div>:!data.renewable?<div className="notice compact"><b>!</b><div><strong>Este contrato no se puede renovar</strong><span>{data.reason}</span></div></div>:!candidates.length?<div className="notice compact"><b>!</b><div><strong>No hay contratos nuevos para esta propiedad</strong><span>Subí el PDF del nuevo contrato en Importaciones, revisalo y confirmalo. Después volvé acá para vincularlo como renovación.</span><button className="button small secondary renewal-imports-link" type="button" onClick={goToImports}>Ir a Importaciones</button></div></div>:<form id="contract-renew-form" className="renewal-candidates" onSubmit={submit}><strong>Seleccionar nuevo contrato</strong>{candidates.map(candidate=><RenewalCandidateCard key={candidate.id} candidate={candidate} selected={selected===candidate.id} onSelect={setSelected}/>)}</form>}</Modal>}
function ContractRescindModal({contract,onClose,actions}){const today=new Date().toISOString().slice(0,10),[form,setForm]=useState({rescission_date:today,penalty_amount:0,return_deposit:false}),[saving,setSaving]=useState(false);useEffect(()=>{if(contract)setForm({rescission_date:today,penalty_amount:0,return_deposit:false});},[contract]);if(!contract)return null;const change=e=>{const{name,value,type,checked}=e.target;setForm(current=>({...current,[name]:type==='checkbox'?checked:value}));};function calculate(){setForm(current=>({...current,penalty_amount:Math.round(Number(contract.initial_amount||0))}));}async function submit(e){e.preventDefault();setSaving(true);try{await post(`contracts/${contract.id}/rescind`,form);actions.notify('Contrato rescindido correctamente.');actions.reload({silent:true});onClose();}catch(error){actions.notify(error.message);}finally{setSaving(false);}}return <Modal open title="Rescindir contrato" subtitle="Se reducirá la duración del contrato a la fecha indicada y se desactivará." onClose={onClose} footer={<><button className="button secondary" type="button" onClick={onClose}>Cancelar</button><button className="button danger" form="contract-rescind-form" disabled={saving}>{saving?'Rescindiendo…':'Rescindir contrato'}</button></>}><form id="contract-rescind-form" className="contract-action-form" onSubmit={submit}><FormField label="Fecha de rescisión" name="rescission_date" type="date" value={form.rescission_date} onChange={change} full required/><div className="field full"><span>Multa por rescisión anticipada</span><div className="inline-money"><MoneyInput value={form.penalty_amount} onChange={value=>setForm(current=>({...current,penalty_amount:value}))}/><button className="button secondary" type="button" onClick={calculate}>▦ Calcular</button></div><small>Presioná “Calcular” para pre-completar según la fórmula estándar.</small></div><label className="check-line full"><input type="checkbox" name="return_deposit" checked={Boolean(form.return_deposit)} onChange={change}/> Se devuelve el depósito al inquilino ({money(contract.deposit_amount||0,contract.currency)})</label></form></Modal>}
function ContractEditModal({contract,onClose,actions}){const[form,setForm]=useState({}),[saving,setSaving]=useState(false);useEffect(()=>{if(contract)setForm({alias:contract.alias||'',rental_type:contract.rental_type||'Residencial',duration_months:contract.duration_months||'',start_date:contract.start_date?.slice(0,10)||'',end_date:contract.end_date?.slice(0,10)||'',initial_amount:contract.initial_amount||'',deposit_amount:contract.deposit_amount||'',adjustment_frequency_months:contract.adjustment_frequency_months||'',adjustment_index:contract.adjustment_index||'',payment_due_day:contract.payment_due_day||10,management_fee_pct:contract.management_fee_pct||3,bank_name:contract.bank_name||'',cbu:contract.cbu||'',status:contract.status||'Activo',notes:contract.notes||''});},[contract]);if(!contract)return null;const change=e=>setForm(current=>({...current,[e.target.name]:e.target.value}));async function submit(e){e.preventDefault();setSaving(true);try{await patch(`contracts/${contract.id}`,form);actions.notify('Contrato actualizado.');actions.reload({silent:true});onClose();}catch(error){actions.notify(error.message);}finally{setSaving(false);}}return <Modal open title="Editar contrato" subtitle={contract.code} onClose={onClose} footer={<><button className="button secondary" type="button" onClick={onClose}>Cancelar</button><button className="button primary" form="contract-edit-form" disabled={saving}>{saving?'Guardando…':'Guardar cambios'}</button></>}><form id="contract-edit-form" className="contract-edit-form" onSubmit={submit}><FormField label="Alias" name="alias" value={form.alias} onChange={change}/><FormField label="Tipo de alquiler" name="rental_type" as="select" value={form.rental_type} onChange={change} options={['Residencial','Comercial','Profesional','Temporario','Otro']}/><FormField label="Inicio" name="start_date" type="date" value={form.start_date} onChange={change}/><FormField label="Fin" name="end_date" type="date" value={form.end_date} onChange={change}/><FormField label="Duración (meses)" name="duration_months" type="number" min="1" value={form.duration_months} onChange={change}/><FormField label="Canon inicial" name="initial_amount" type="number" min="0" step="0.01" value={form.initial_amount} onChange={change}/><FormField label="Depósito" name="deposit_amount" type="number" min="0" step="0.01" value={form.deposit_amount} onChange={change}/><FormField label="Honorario (%)" name="management_fee_pct" type="number" min="2" max="5" step="0.1" value={form.management_fee_pct} onChange={change}/><FormField label="Ajuste cada (meses)" name="adjustment_frequency_months" type="number" value={form.adjustment_frequency_months} onChange={change}/><FormField label="Índice" name="adjustment_index" as="select" value={form.adjustment_index} onChange={change} options={['','IPC','ICL','CAC','Acuerdo de partes']}/><FormField label="Día de vencimiento" name="payment_due_day" type="number" min="1" max="31" value={form.payment_due_day} onChange={change}/><FormField label="Estado" name="status" as="select" value={form.status} onChange={change} options={['Activo','Borrador','Revisión','Finalizado','Vencido','Rescindido','Renovado','Anulado','Archivado']}/><FormField label="Banco" name="bank_name" value={form.bank_name} onChange={change}/><FormField label="CBU" name="cbu" value={form.cbu} onChange={change}/><FormField label="Notas" name="notes" as="textarea" value={form.notes} onChange={change} full/></form></Modal>}
function ContractInfoModal({contract,type,onClose}){if(!contract||!type)return null;const titles={details:'Detalles del contrato',guarantee:'Garantía',tenant:'Inquilino',owner:'Propietario'};return <Modal open title={titles[type]} subtitle={contract.code} onClose={onClose}><div className="contract-info-grid">{type==='details'&&<><span>Propiedad</span><b>{contract.property}</b><span>Inquilino</span><b>{contract.tenant}</b><span>Propietarios</span><b>{contract.owners||'—'}</b><span>Vigencia</span><b>{shortDate(contract.start_date)} → {shortDate(contract.end_date)}</b><span>Canon</span><b>{money(contract.initial_amount,contract.currency)}</b><span>Depósito</span><b>{money(contract.deposit_amount||0,contract.currency)}</b><span>Estado</span><b>{contract.status}</b><span>Documento</span><b>{contract.document_filename||contract.document_path||'—'}</b>{contract.previous_contract_code&&<><span>Renueva al contrato</span><b>{contract.previous_contract_code}</b></>}{contract.next_contract_code&&<><span>Renovado por</span><b>{contract.next_contract_code}</b></>}</>}{type==='guarantee'&&<><span>Tipo</span><b>{contract.guarantee_type||'—'}</b><span>Proveedor</span><b>{contract.provider_detail||contract.provider||'—'}</b><span>Garante</span><b>{contract.guarantor_name||'—'}</b><span>Documento</span><b>{contract.guarantor_document||'—'}</b><span>Propiedad garantizada</span><b>{contract.guaranteed_property||'—'}</b></>}{type==='tenant'&&<><span>Nombre</span><b>{contract.tenant}</b><span>ID</span><b>{contract.tenant_id}</b></>}{type==='owner'&&<><span>Propietarios</span><b>{contract.owners||'Sin propietario'}</b><span>IDs</span><b>{contract.owner_ids||'—'}</b></>}</div></Modal>}
function ContractActionMenu({row,actions}){const[open,setOpen]=useState(false),[renew,setRenew]=useState(false),[rescind,setRescind]=useState(false),[edit,setEdit]=useState(false),[info,setInfo]=useState(null),[menuStyle,setMenuStyle]=useState({}),fileRef=useRef(null),buttonRef=useRef(null),menuRef=useRef(null);useEffect(()=>{if(!open)return;const placeMenu=()=>{const button=buttonRef.current;if(!button)return;const rect=button.getBoundingClientRect(),menuWidth=225,menuHeight=570,gap=8,margin=14;const left=Math.min(window.innerWidth-menuWidth-margin,Math.max(margin,rect.right-menuWidth));let top=rect.bottom+gap;if(top+menuHeight>window.innerHeight-margin)top=Math.max(margin,rect.top-menuHeight-gap);setMenuStyle({left:`${left}px`,top:`${top}px`});};const closeOnOutside=event=>{if(buttonRef.current?.contains(event.target)||menuRef.current?.contains(event.target))return;setOpen(false);};placeMenu();window.addEventListener('resize',placeMenu);window.addEventListener('scroll',placeMenu,true);document.addEventListener('mousedown',closeOnOutside);return()=>{window.removeEventListener('resize',placeMenu);window.removeEventListener('scroll',placeMenu,true);document.removeEventListener('mousedown',closeOnOutside);};},[open]);const runAction=callback=>{setOpen(false);callback();};const navigate=(hash,message)=>{location.hash=hash;actions.notify(message);};async function upload(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;const formData=new FormData();formData.append('file',file);try{const res=await fetch(`/api/contracts/${row.id}/upload-file`,{method:'POST',body:formData});const data=await res.json();if(!res.ok)throw new Error(data.error||`Error ${res.status}`);actions.notify(`Archivo adjuntado al contrato: ${file.name}`);actions.reload({silent:true});}catch(error){actions.notify(error.message);}}async function simple(endpoint,message,body={}){try{await post(`contracts/${row.id}/${endpoint}`,body);actions.notify(message);actions.reload({silent:true});}catch(error){actions.notify(error.message);}}async function remove(){if(!confirm(`¿Eliminar definitivamente el contrato ${row.code}? Se borrarán cuotas, cobros y documentos asociados.`))return;try{await api(`contracts/${row.id}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:'Eliminado desde acciones de contrato'})});actions.notify('Contrato eliminado.');actions.reload({silent:true});}catch(error){actions.notify(error.message);}}async function deposit(){const value=prompt('Importe a devolver',String(row.deposit_amount||0));if(value===null)return;await simple('return-deposit','Depósito registrado como devuelto.',{amount:Number(value),date:new Date().toISOString().slice(0,10)});}return <div className="contract-actions"><button ref={buttonRef} className="button small secondary" type="button" onClick={()=>setOpen(current=>!current)}>Ver acciones</button>{open&&<div ref={menuRef} className="contract-action-menu floating" style={menuStyle}><button onClick={()=>runAction(()=>setInfo('details'))}>▤ Ver más detalles</button><button onClick={()=>runAction(()=>setInfo('tenant'))}>♙ Ver inquilino</button><button onClick={()=>runAction(()=>setInfo('owner'))}>▥ Ver propietario</button><button onClick={()=>runAction(()=>navigate('collections','Mostrando cobros. Usá el contrato como referencia para filtrar visualmente.'))}>▣ Ver últimos cobros</button><button onClick={()=>runAction(()=>navigate('pending-collections','Mostrando cobros pendientes.'))}>▦ Ver cobros pendientes</button><button onClick={()=>runAction(()=>setInfo('guarantee'))}>▤ Ver garantía</button><button onClick={()=>runAction(()=>navigate('expenses','Mostrando gastos.'))}>▣ Ver gastos</button><button onClick={()=>runAction(()=>fileRef.current?.click())}>↥ Subir archivos</button><button onClick={()=>runAction(()=>setRenew(true))}>⟳ Renovar contrato</button><button className="warn" onClick={()=>runAction(()=>setRescind(true))}>⌫ Rescindir contrato</button><button onClick={()=>runAction(()=>setEdit(true))}>✎ Editar contrato</button><button className="warn" onClick={()=>runAction(deposit)}>$ Devolver depósito</button><button className="warn" onClick={()=>runAction(()=>simple('deactivate','Contrato desactivado.',{reason:'Desactivado desde menú de acciones'}))}>▱ Desactivar</button><button className="danger" onClick={()=>runAction(remove)}>⌧ Eliminar contrato</button></div>}<input ref={fileRef} type="file" accept="application/pdf" hidden onChange={upload}/><ContractRenewModal contract={renew?row:null} onClose={()=>setRenew(false)} actions={actions}/><ContractRescindModal contract={rescind?row:null} onClose={()=>setRescind(false)} actions={actions}/><ContractEditModal contract={edit?row:null} onClose={()=>setEdit(false)} actions={actions}/><ContractInfoModal contract={row} type={info} onClose={()=>setInfo(null)}/></div>}
function makeColumns(resource,actions){
  const map={
    contracts:[{key:'contract',label:'Contrato / propiedad',render:r=>primary(r.code,r.property)},{key:'tenant',label:'Inquilino',render:r=>primary(r.tenant,r.owners||'Sin propietario')},{key:'term',label:'Vigencia',render:r=>primary(`${r.duration_months} meses`,`${shortDate(r.start_date)} → ${shortDate(r.end_date)}`)},{key:'amount',label:'Canon inicial',render:r=>primary(money(r.initial_amount,r.currency),`Honorario ${r.management_fee_pct}%`)},{key:'adjustment',label:'Ajuste',render:r=>primary(r.adjustment_index||r.adjustment_type||'Sin índice',`Cada ${r.adjustment_frequency_months||'—'} meses`)},{key:'guarantee',label:'Garantía',render:r=>primary(r.guarantee_type,r.provider_detail||r.provider)},{key:'status',label:'Estado',render:r=><StatusPill>{r.status}</StatusPill>},{key:'action',label:'',render:r=><ContractActionMenu row={r} actions={actions}/>}],
    properties:[{key:'property',label:'Inmueble',render:r=>primary(r.address,r.code)},{key:'type',label:'Tipo',render:r=>r.property_type},{key:'owners',label:'Propietarios',render:r=>r.owners||'Sin asignar'},{key:'status',label:'Estado',render:r=><StatusPill>{r.status}</StatusPill>},{key:'contracts',label:'Contratos activos',render:r=>r.active_contracts}],
    people:[{key:'name',label:'Nombre',render:r=><strong>{r.full_name}</strong>},{key:'document',label:'Documento',render:r=>`${r.document_type} ${r.document_number||'—'}`},{key:'role',label:'Rol',render:r=><div className="pill-group">{r.owner_role&&<StatusPill>{r.owner_role}</StatusPill>}{r.tenant_role&&<StatusPill>{r.tenant_role}</StatusPill>}</div>},{key:'contact',label:'Contacto',render:r=>primary(r.email||'—',r.phone)},{key:'address',label:'Domicilio',render:r=>r.address||'—'}],
    collections:[{key:'period',label:'Período',render:r=>primary(r.period,r.contract_code)},{key:'property',label:'Propiedad / inquilino',render:r=>primary(r.property,r.tenant)},{key:'due',label:'Vencimiento',render:r=>shortDate(r.due_date)},{key:'expected',label:'Esperado',render:r=>primary(money(r.expected_amount,r.currency),r.adjustment_pending?'Requiere ajuste':null)},{key:'paid',label:'Pagado',render:r=>money(r.paid_amount,r.currency)},{key:'status',label:'Estado',render:r=><StatusPill>{installmentStatus(r)}</StatusPill>},{key:'action',label:'',render:r=>r.status!=='Pagado'&&<button className="button small primary" onClick={()=>actions.setPayment(r)}>Registrar pago</button>}],
    incidents:[{key:'title',label:'Incidencia',render:r=>primary(r.title,r.description)},{key:'property',label:'Propiedad',render:r=>r.property||'General'},{key:'priority',label:'Prioridad',render:r=><StatusPill>{r.priority}</StatusPill>},{key:'opened',label:'Apertura',render:r=>shortDate(r.opened_at)},{key:'status',label:'Estado',render:r=><StatusPill>{r.status}</StatusPill>},{key:'action',label:'',render:r=>!['Resuelta','Cerrada'].includes(r.status)&&<button className="button small secondary" onClick={async()=>{try{await patch(`incidents/${r.id}`,{status:'Resuelta'});actions.notify('Incidencia resuelta.');actions.reload();}catch(error){actions.notify(error.message);}}}>Resolver</button>}],
    ledger:[{key:'date',label:'Fecha',render:r=>shortDate(r.entry_date)},{key:'kind',label:'Tipo',render:r=><StatusPill>{r.kind}</StatusPill>},{key:'category',label:'Categoría',render:r=>r.category},{key:'description',label:'Detalle',render:r=><strong>{r.description}</strong>},{key:'property',label:'Propiedad',render:r=>r.property||'General'},{key:'amount',label:'Importe',render:r=><b>{r.kind==='Gasto'?'- ':'+ '}{money(r.amount,r.currency)}</b>}],
    documents:[{key:'file',label:'Documento',render:r=>primary(r.filename,'PDF')},{key:'property',label:'Propiedad',render:r=>r.property||'—'},{key:'contract',label:'Contrato',render:r=>r.contract_code||'—'},{key:'date',label:'Importado',render:r=>shortDate(r.imported_at)},{key:'path',label:'Ruta',render:r=><code>{r.absolute_path}</code>}],
    imports:[{key:'file',label:'Archivo',render:r=>primary(r.filename,r.absolute_path)},{key:'result',label:'Resultado',render:r=><StatusPill>{r.status}</StatusPill>},{key:'confidence',label:'Confianza',render:r=>r.confidence==null?'—':`${Math.round(r.confidence*100)}%`},{key:'date',label:'Fecha',render:r=>shortDate(r.created_at)},{key:'warnings',label:'Observaciones',render:r=>{const missing=r.result_json?.blocking_fields||r.result_json?.missing_fields||[],warnings=r.result_json?.warnings||r.warnings||[],summary=r.result_json?.revert_summary;return <>{r.error_message?<span className="error-text">{r.error_message}</span>:null}{missing.length?<ul className="warnings">{missing.map(item=><li key={item.key}>{item.message}</li>)}</ul>:warnings.length?<ul className="warnings">{warnings.map(item=><li key={item}>{item}</li>)}</ul>:summary?<small>Revertido: contrato {summary.deleted?.contracts||0}, documento {summary.deleted?.documents||0}, propiedad {summary.deleted?.properties||0}, personas {summary.deleted?.persons||0}.</small>:'Sin observaciones'}</>}},{key:'action',label:'',render:r=><div className="action-stack">{r.status==='Revisión'&&<button className="button small primary" onClick={()=>actions.setReviewing(r)}>{(r.result_json?.blocking_fields||r.result_json?.missing_fields||[]).length?'Completar':'Revisar'}</button>}{['Revisión','Error','Omitido'].includes(r.status)&&<button className="button small secondary" onClick={()=>discardImport(r,actions)}>Descartar</button>}{r.status==='Procesado'&&<button className="button small danger" onClick={()=>revertImport(r,actions)}>Revertir</button>}</div>}]
  };return map[resource];
}


